document.addEventListener("DOMContentLoaded",()=>{const e=window.matchMedia("(max-width: 768px)").matches;document.querySelectorAll("sup[id^='fnref']").forEach(t=>{const s=t.querySelector("a");if(!s)return;const i=s.getAttribute("href")?.replace("#",""),o=document.getElementById(i);if(!o)return;const a=o.innerHTML,n=document.createElement("span");n.className="sidenote",n.innerHTML=a,t.after(n),e&&(n.classList.add("collapsed"),t.addEventListener("click",e=>{e.preventDefault(),n.classList.toggle("collapsed")}))})})